async function assertSalonAdmin(userId, salonId) {
  const membership = await findMembership(userId, salonId);
  if (!membership || membership.role !== "owner" && membership.role !== "admin") {
    throw new TRPCError({
      code: "FORBIDDEN",
      message: "Acesso negado a este estabelecimento."
    });
  }
}
async function assertSalonOwner(userId, salonId) {
  const membership = await findMembership(userId, salonId);
  if (!membership || membership.role !== "owner") {
    throw new TRPCError({
      code: "FORBIDDEN",
      message: "Somente o dono do estabelecimento pode fazer isso."
    });
  }
}

