// server/lib/format.ts
function capitalizeWords(value) {
  return value.trim().replace(/\s+/g, " ").split(" ").map((word) => word.charAt(0).toLocaleUpperCase("pt-BR") + word.slice(1).toLocaleLowerCase("pt-BR")).join(" ");
}

